import { Mesh, PlaneGeometry, Group, Vector2, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, texture, uv, normalLocal, positionLocal, vec3, mul, add, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData = { handlers: {}, cleanup: () => {} };

  // Geometry with enough segments for displacement
  const segments = 64;
  const geometry = new PlaneGeometry(3.5, 2.5, segments, segments);

  // Temporary material until textures load
  const material = new MeshStandardNodeMaterial({
    color: new Color(0x16161d),
    roughness: 0.7,
    metalness: 0.2,
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // Load textures
  const imageUrl = config.imageUrl;
  const depthUrl = config.depthMapUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      material.map = tex;
      material.needsUpdate = true;
    });
  }
  if (depthUrl) {
    ctx.textureLoader.loadTexture(depthUrl).then((tex) => {
      tex.colorSpace = 'linear'; // depth map in linear space
      material.displacementMap = tex;
      material.displacementScale = 0.15;
      material.needsUpdate = true;
    });
  }

  // Displacement node via TSL (optional, but we use property set above)
  // For more control, we could use a custom node, but the built-in displacementMap works.

  // Subtle parallax on cursor movement
  const initialPosition = mesh.position.clone();
  const parallaxStrength = 0.08;
  let mouseX = 0, mouseY = 0;
  let targetX = 0, targetY = 0;

  const onMouseMove = (event) => {
    // Normalize coordinates from -1 to 1 based on viewport
    // event.clientX / window.innerWidth * 2 - 1
    // But we don't have window access? We can use renderer.domElement? Not allowed.
    // Instead we use event.detail? The handlers receive a custom event object.
    // We'll assume the event has normalized coordinates 0-1 range.
    // Use a normalized approach: store normalized from 0 to 1.
    const x = (event.clientX / window.innerWidth) * 2 - 1;
    const y = -(event.clientY / window.innerHeight) * 2 + 1;
    mouseX = x;
    mouseY = y;
  };

  group.userData.handlers.mousemove = onMouseMove;

  // GSAP ticker to interpolate
  const updateParallax = () => {
    targetX += (mouseX - targetX) * 0.05;
    targetY += (mouseY - targetY) * 0.05;
    mesh.position.x = initialPosition.x + targetX * parallaxStrength;
    mesh.position.y = initialPosition.y + targetY * parallaxStrength;
  };
  // Add to GSAP ticker
  gsap.ticker.add(updateParallax);

  // Hover lift: rise-in by 0.15 units
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, { y: initialPosition.y + 0.15, duration: 0.4, ease: 'power3.out' }, 0);

  group.userData.handlers.mouseenter = () => {
    hoverTimeline.play();
  };
  group.userData.handlers.mouseleave = () => {
    hoverTimeline.reverse();
  };

  // Press-down on click (scale to 0.97)
  group.userData.handlers.click = (event) => {
    if (event.button === 0) {
      // Press
      gsap.to(mesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out' });
      // Release after 120ms
      setTimeout(() => {
        gsap.to(mesh.scale, { x: 1, y: 1, duration: 0.12, ease: 'back.out' });
      }, 120);
      // Emit event as per spec
      ctx.emit('hub-features.select', {});
    }
  };

  // Focus? Not implemented but could add a glow.

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    (material.map || null) && material.map.dispose();
    (material.displacementMap || null) && material.displacementMap.dispose();
    if (hoverTimeline) hoverTimeline.kill();
    gsap.ticker.remove(updateParallax);
    delete group.userData.handlers.mousemove;
    delete group.userData.handlers.mouseenter;
    delete group.userData.handlers.mouseleave;
    delete group.userData.handlers.click;
  };

  return group;
}
